import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int totalNumbers = scanner.nextInt();
        int budget = scanner.nextInt();
        int[] data = new int[totalNumbers];
        int evenCount = 0, oddCount = 0;
        for (int i = 0; i < totalNumbers; i++) {
            data[i] = scanner.nextInt();
            if (data[i] % 2 == 0) {
                evenCount++;
            } else {
                oddCount++;
            }
        }
        if (evenCount != oddCount) {
            System.out.println(0);
        } else {
            List<Integer> differences = new ArrayList<>();
            int sumDifferences = 0;
            int evenPairsCount = 0, oddPairsCount = 0;
            for (int i = 0; i < totalNumbers - 1; i++) {
                if (data[i] % 2 == 0) {
                    evenPairsCount++;
                } else {
                    oddPairsCount++;
                }
                if (evenPairsCount == oddPairsCount) {
                    differences.add(Math.abs(data[i + 1] - data[i]));
                }
            }
            Collections.sort(differences);
            int currentSum = 0, selectedCount = 0;
            for (int diff : differences) {
                if (currentSum + diff <= budget) {
                    currentSum += diff;
                    selectedCount++;
                } else {
                    break;
                }
            }
            System.out.println(selectedCount);
        }
    }
}
